from fractions import Fraction as F
import json
rows=[('A',5,[0,0,0,1]),('A',6,[1,0,1,0]),('B',11,[0,0,0,1]),('B',5,[0,1,1,0]),('C',6,[0,1,0,1]),('C',4,[1,0,1,1]),('D',6,[0,0,1,0]),('D',8,[1,1,0,0])]
names='TUVW'
cost=[F(1),F(1),F(17,10),F(21,10)]
loss=[[0,7,10,21],[7,0,22,11],[19,13,0,19],[12,6,13,0]]
def stop(s):
    z=sum(rows[i][1] for i in s)
    return min((F(sum(rows[i][1]*loss[a]['ABCD'.index(rows[i][0])] for i in s),z),'ABCD'[a]) for a in range(4))
def solve(s,remaining,budget):
    best=stop(s)
    if budget:
        for t in remaining:
            v=buy(s,remaining,budget,t)
            best=min(best,(v,names[t]))
    return best
def buy(s,remaining,budget,t):
    z=sum(rows[i][1] for i in s)
    val=cost[t]
    for b in (0,1):
        sub=tuple(i for i in s if rows[i][2][t]==b)
        if sub:
            val+=F(sum(rows[i][1] for i in sub),z)*solve(sub,tuple(x for x in remaining if x!=t),budget-1)[0]
    return val
s=tuple(range(8)); remaining=tuple(range(4))
fl={'STOP':float(stop(s)[0])}
for t in remaining: fl[names[t]]=float(buy(s,remaining,2,t))
v,action=solve(s,remaining,2)
next_actions={}
if action in names:
    t=names.index(action)
    for b in (0,1):
        sub=tuple(i for i in s if rows[i][2][t]==b)
        next_actions[str(b)]=solve(sub,tuple(x for x in remaining if x!=t),1)[1] if sub else 'IMPOSSIBLE'
print(json.dumps({'first':action,'first_losses':fl,'next':next_actions}))

