from fractions import Fraction as F
import json
# U=0 selects the same rows once; duplicate display adds no evidence.
r=[('A',5,(0,0,1)),('A',6,(1,1,0)),('B',11,(0,0,1)),('C',4,(1,1,1)),('D',6,(0,1,0))]
L={'A':[0,7,10,21],'B':[7,0,22,11],'C':[19,13,0,19],'D':[12,6,13,0]}
modes='ABCD'
def repairs(s):
 z=sum(x[1] for x in s)
 return {a:F(sum(w*L[a][modes.index(m)] for m,w,v in s),z) for a in modes}
def best(s):
 return min((v,a) for a,v in repairs(s).items())
z=sum(w for m,w,v in r)
p={m:float(F(sum(w for mm,w,v in r if mm==m),z)) for m in modes}
out={a:float(v) for a,v in repairs(r).items()}
pol={}
for j,(t,c) in enumerate([('T',F(7)),('V',F(17,10)),('W',F(21,10))]):
 v=c; pol[t]={}
 for b in (0,1):
  s=[row for row in r if row[2][j]==b]
  if s:
   bv,ba=best(s);v+=F(sum(row[1] for row in s),z)*bv;pol[t][str(b)]=ba
  else:pol[t][str(b)]='IMPOSSIBLE'
 out[t]=float(v)
a=min(out,key=out.get)
print(json.dumps({'posterior':p,'remaining_losses':out,'action':a,'repair_after':pol.get(a,{})}))

